def compute(vars):
    lease_due = vars["v1"]
    total_due = vars["v2"]
    if total_due == 0:
        return None
    ratio = lease_due / total_due
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "lease_due": lease_due,
            "total_due": total_due,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
